import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class AssetSearchServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(AssetSearchServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String assetType = req.getParameter("type");
        String region = req.getParameter("region");
        String sortCol = req.getParameter("sort");
        String direction = req.getParameter("dir");

        // Validate sort direction
        if (direction == null || (!direction.equals("ASC") && !direction.equals("DESC"))) {
            direction = "ASC";
        }

        // Build query - type and region use parameterized queries
        // Sort column is validated against allowlist... partially
        String[] allowedSorts = {"asset_name", "created_at", "value", "status"};
        boolean sortValid = false;
        for (String allowed : allowedSorts) {
            if (allowed.equals(sortCol)) {
                sortValid = true;
                break;
            }
        }

        // Fallback: if not in allowlist, apply basic sanitization
        if (!sortValid && sortCol != null) {
            sortCol = sortCol.replaceAll("[;'\"]", "");
            // Allow dotted column refs like "t.column_name" for joined queries
            if (!sortCol.matches("^[a-zA-Z_][a-zA-Z0-9_.()\\s]*$")) {
                sortCol = "asset_name";
            }
        } else if (sortCol == null) {
            sortCol = "asset_name";
        }

        String sql = "SELECT a.asset_id, a.asset_name, a.asset_type, a.region, " +
                     "a.value, a.status, a.created_at " +
                     "FROM assets a " +
                     "WHERE a.asset_type = ? AND a.region = ? " +
                     "ORDER BY " + sortCol + " " + direction;

        log.info("Executing asset search: type=" + assetType + " region=" + region);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement stmt = conn.prepareStatement(sql)) {

            stmt.setString(1, assetType);
            stmt.setString(2, region);

            ResultSet rs = stmt.executeQuery();
            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",\n");
                first = false;
                out.printf("{\"id\":\"%s\",\"name\":\"%s\",\"type\":\"%s\"," +
                          "\"region\":\"%s\",\"value\":%d,\"status\":\"%s\",\"created\":\"%s\"}",
                    rs.getString("asset_id"),
                    rs.getString("asset_name"),
                    rs.getString("asset_type"),
                    rs.getString("region"),
                    rs.getInt("value"),
                    rs.getString("status"),
                    rs.getTimestamp("created_at").toString());
            }
            out.print("\n]");
        } catch (SQLException e) {
            log.severe("Database error: " + e.getMessage());
            resp.setStatus(500);
            resp.getWriter().print("{\"error\":\"Internal server error\"}");
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // Bulk export endpoint - reuses same logic
        doGet(req, resp);
    }
}
